+        Files.write(elf, buildMinimalElf64("/lib64/ld-linux-x86-64.so.2"));
+        String interp = PlatformDetector.readElfPtInterp(elf);
+        assertEquals("/lib64/ld-linux-x86-64.so.2", interp);
+    }
