+        dos.writeByte('E');
+        dos.writeByte('L');
+        dos.writeByte('F');
+        dos.writeByte(2);
+        dos.writeByte(1);
+        dos.writeByte(1);
+        dos.writeByte(0);
+        dos.write(new byte[8]);
+        writeUInt16Le(dos, 2);
+        writeUInt16Le(dos, 62);
+        writeUInt32Le(dos, 1);
+        writeUInt64Le(dos, 0);
+        writeUInt64Le(dos, phdrOffset);
+        writeUInt64Le(dos, 0);
+        writeUInt32Le(dos, 0);
+        writeUInt16Le(dos, 64);
+        writeUInt16Le(dos, phdrSize);
+        writeUInt16Le(dos, 1);
+        writeUInt16Le(dos, 64);
+        writeUInt16Le(dos, 0);
+        writeUInt16Le(dos, 0);
+
+        writeUInt32Le(dos, 3);
+        writeUInt32Le(dos, 4);
+        writeUInt64Le(dos, interpOffset);
+        writeUInt64Le(dos, 0);
+        writeUInt64Le(dos, 0);
+        writeUInt64Le(dos, interpSize);
+        writeUInt64Le(dos, interpSize);
+        writeUInt64Le(dos, 1);
+
+        dos.write(interpBytes);
+        dos.writeByte(0);
+
+        dos.flush();
+        return bos.toByteArray();
+    }
